// Источник: web-тест .qa/e2e/tests/guided-prayer/gp-01-run-without-finish.spec.ts, план .qa/e2e/specs/guided-prayer.md, кейс .qa/tests/guided-prayer/GP-01-run-without-finish.md
// Тикет #6a86f7e9 · 4d0f208d1b1b «פיתוח: הרצת תפילה מודרכת עד סיום». Опора: F-96 AC1–AC6 · S-17.
// «סיים תפילה» НЕ нажимается (иначе запись в историю). Позицию в молитве web возвращал через localStorage — здесь не возвращается (данные аккаунта не меняются).
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, byLabel, tapText, tapLabel, expectVisibleText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

const PRAYERS: Record<string, string> = { 'שחרית': 'shacharit', 'מנחה': 'mincha', 'ערבית': 'arvit' };
const NUSACH: Record<string, string> = { 'אשכנז': 'ashkenaz', 'ספרד': 'sfarad' };

/** «התחל תפילה»: активна — нажать; неактивна вне окна молитвы («… מתחילה ב-HH:MM», норма) — открыть ту же молитву из «תפילות». */
async function startNearestPrayer() {
  const start = await byLabel('התחל תפילה');
  await start.waitForDisplayed({ timeout: 20000 });
  if (await start.isEnabled()) { await start.click(); return; }
  const startsAt = await byTextMatches('.*מתחילה ב-?\\s?\\d{1,2}:\\d{2}.*');
  await expect(startsAt).toBeDisplayed();
  const line = await startsAt.getText();
  const prayer = Object.keys(PRAYERS).find((p) => line.includes(p));
  const nusach = (await (await byTextMatches('.*נוסח (אשכנז|ספרד).*')).getText()).match(/נוסח (אשכנז|ספרד)/)?.[1];
  expect(prayer).toBeTruthy();
  expect(nusach).toBeTruthy();
  await openPrayer(`${PRAYERS[prayer!]}_${NUSACH[nusach!]}`, prayer!);
}

async function counterIs(expected: string) {
  await driver.waitUntil(async () => (await pageCounter()) === expected, { timeoutMsg: `Счётчик не стал «${expected}»` });
}

describe('Молитва по шагам', () => {
  afterEach(async () => { await toHome(); });

  it('GP-01 Молитва: шапка, «X מתוך Y», המשך/קודם, выход и возврат на тот же חלק #6a86f7e9 @prod-safe', async () => {
    // 1. Главная → «התחל תפילה»; если открылась не מנחה (אשכנזי) — открыть её из «תפילות».
    await startNearestPrayer();
    await (await byTextMatches('\\d+ מתוך \\d+')).waitForDisplayed();
    if (!(await (await byText('מנחה (אשכנזי)')).isDisplayed().catch(() => false))) {
      await toHome();
      await openPrayer('mincha_ashkenaz', 'מנחה');
    }
    await expectVisibleText('מנחה (אשכנזי)');
    // Часть: текст с никудом.
    await expect(byTextMatches('.*[\\u05B0-\\u05C7].*')).toBeDisplayed();

    // 2. Запомнить «N מתוך M». «המשך» → N+1; «קודם» → N; «המשך» → N+1 (позиция — не последняя).
    let [n, total] = (await pageCounter()).split(' מתוך ').map(Number);
    if (n >= total) { await tapText('קודם'); await counterIs(`${total - 1} מתוך ${total}`); n = total - 1; }
    await tapText('המשך');
    await counterIs(`${n + 1} מתוך ${total}`);
    await tapText('קודם');
    await counterIs(`${n} מתוך ${total}`);
    await tapText('המשך');
    await counterIs(`${n + 1} מתוך ${total}`);

    // «סיים תפילה» видна и активна — НЕ нажимать.
    const finish = await byText('סיים תפילה');
    await expect(finish).toBeDisplayed();
    await expect(finish).toBeEnabled();

    // 3. «חזרה» → главная; снова открыть מנחה — та же часть.
    await tapLabel('חזרה');
    await expect(byLabel('התחל תפילה')).toBeDisplayed();
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await counterIs(`${n + 1} מתוך ${total}`);
    await expect(byTextContains('(אשכנזי)')).toBeDisplayed();
  });
});
